import argparse, json, os, re, shutil, subprocess, sys

HOME = os.path.expanduser("~")
STATE = os.path.join(os.environ.get("XDG_CACHE_HOME") or os.path.join(HOME, ".cache"), "claude-chat")
CONFIG = os.path.join(os.environ.get("XDG_CONFIG_HOME") or os.path.join(HOME, ".config"), "claude-chat", "config.json")
SHARE = os.path.join(HOME, ".local", "share", "claude-chat")
SETTINGS = os.path.join(HOME, ".claude", "settings.json")
OUR_COMMAND = "python3 ~/.local/share/claude-chat/statusline.py"
STATUSLINE_SRC = "import json, os, re, subprocess, sys, time\n\nHOME = os.path.expanduser(\"~\")\nSTATE = os.path.join(os.environ.get(\"XDG_CACHE_HOME\") or os.path.join(HOME, \".cache\"), \"claude-chat\")\nCONFIG = os.path.join(os.environ.get(\"XDG_CONFIG_HOME\") or os.path.join(HOME, \".config\"), \"claude-chat\", \"config.json\")\nSAMPLE_EVERY = 180\nKEEP = 2 * 86400\n\n\ndef write_atomic(path, text):\n    os.makedirs(os.path.dirname(path), exist_ok=True)\n    tmp = \"%s.%d.tmp\" % (path, os.getpid())\n    with open(tmp, \"w\") as fh:\n        fh.write(text)\n    os.replace(tmp, path)\n\n\ndef save_status(payload, now):\n    sid = str(payload.get(\"session_id\") or \"\")\n    if re.fullmatch(r\"[0-9A-Za-z_-]+\", sid):\n        write_atomic(os.path.join(STATE, \"statusline\", sid + \".json\"), json.dumps({\"payload\": payload, \"updatedAt\": now}))\n\n\ndef save_sample(payload, now):\n    import fcntl\n    rl = payload.get(\"rate_limits\") or {}\n    five = (rl.get(\"five_hour\") or {}).get(\"used_percentage\")\n    seven = (rl.get(\"seven_day\") or {}).get(\"used_percentage\")\n    if five is None and seven is None:\n        return\n    path = os.path.join(STATE, \"usage-history.jsonl\")\n    os.makedirs(STATE, exist_ok=True)\n    with open(path + \".lock\", \"w\") as lock:\n        fcntl.flock(lock, fcntl.LOCK_EX)\n        try:\n            with open(path) as fh:\n                lines = fh.read().splitlines()\n        except OSError:\n            lines = []\n        rows = []\n        for line in lines:\n            try:\n                rows.append(json.loads(line))\n            except ValueError:\n                pass\n        if rows and now - rows[-1].get(\"ts\", 0) < SAMPLE_EVERY:\n            return\n        sample = json.dumps({\"ts\": int(now), \"five\": five, \"seven\": seven})\n        kept = [r for r in rows if r.get(\"ts\", 0) >= now - KEEP]\n        if len(kept) == len(lines):\n            with open(path, \"a\") as fh:\n                fh.write(sample + \"\\n\")\n        else:\n            write_atomic(path, \"\".join(json.dumps(r) + \"\\n\" for r in kept) + sample + \"\\n\")\n\n\ndef default_line(payload):\n    model = (payload.get(\"model\") or {}).get(\"display_name\") or \"Claude\"\n    pct = (payload.get(\"context_window\") or {}).get(\"used_percentage\")\n    return model if pct is None else \"%s \u00b7 ctx %d%%\" % (model, pct)\n\n\ndef main():\n    raw = sys.stdin.buffer.read()\n    now = time.time()\n    try:\n        payload = json.loads(raw.decode(\"utf-8\", \"replace\"))\n    except ValueError:\n        payload = None\n    payload = payload if isinstance(payload, dict) else {}\n    for save in (save_status, save_sample):\n        try:\n            save(payload, now)\n        except Exception:\n            pass\n    try:\n        with open(CONFIG) as fh:\n            chain = json.load(fh).get(\"statuslineChain\")\n    except Exception:\n        chain = None\n    if chain:\n        try:\n            r = subprocess.run(chain, shell=True, input=raw, stdout=subprocess.PIPE, timeout=5)\n            sys.stdout.buffer.write(r.stdout)\n            return\n        except Exception:\n            pass\n    try:\n        line = default_line(payload)\n    except Exception:\n        line = \"Claude\"\n    sys.stdout.buffer.write((line + \"\\n\").encode(\"utf-8\"))\n\n\nmain()\n"  # generated by build.py


def fail(msg):
    raise SystemExit("claude-chat setup: " + msg)


def read_json(path, default):
    try:
        with open(path) as fh:
            return json.load(fh)
    except FileNotFoundError:
        return default
    except ValueError as e:
        fail("%s is not valid JSON (%s)" % (path, e))


def write_json(path, data):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    tmp = path + ".claude-chat-tmp"
    with open(tmp, "w") as fh:
        json.dump(data, fh, indent=2, ensure_ascii=False)
        fh.write("\n")
    os.replace(tmp, path)


def is_ours(command):
    return "claude-chat/statusline.py" in (command or "")


def which(name, *extra):
    for c in [shutil.which(name)] + [os.path.join(HOME, x) for x in extra]:
        if c and os.access(c, os.X_OK):
            return c
    return None


def install_statusline(config, done):
    os.makedirs(SHARE, exist_ok=True)
    target = os.path.join(SHARE, "statusline.py")
    with open(target, "w") as fh:
        fh.write(STATUSLINE_SRC)
    os.chmod(target, 0o755)
    done.append("installed " + target)
    settings = read_json(SETTINGS, {})
    if not isinstance(settings, dict):
        fail(SETTINGS + " is not a JSON object")
    prev = settings.get("statusLine") if isinstance(settings.get("statusLine"), dict) else {}
    if is_ours(prev.get("command")):
        done.append("statusLine already set")
        return
    if prev.get("command"):
        config["statuslineChain"] = prev["command"]
        done.append("chained previous statusLine: " + prev["command"])
    bak = SETTINGS + ".claude-chat-bak"
    if os.path.exists(SETTINGS) and not os.path.exists(bak):
        shutil.copy2(SETTINGS, bak)
        done.append("backup " + bak)
    line = dict(prev)
    line.update({"type": "command", "command": OUR_COMMAND})
    settings["statusLine"] = line
    write_json(SETTINGS, settings)
    done.append("statusLine -> " + OUR_COMMAND)


# What the page last installed for itself under a folder named after its version, else what 2.x installed.
def package_cli():
    try:
        names = [n for n in os.listdir(SHARE) if re.match(r"^\d+\.\d+\.\d+-[0-9a-f]{12}$", n)]
    except OSError:
        names = []
    found = [c for c in (os.path.join(SHARE, n, "claude_chat", "cli.py") for n in names) if os.path.isfile(c)]
    if found:
        return max(found, key=os.path.getmtime)
    old = os.path.join(SHARE, "claude_chat", "cli.py")
    return old if os.path.isfile(old) else None


def cli_list():
    cli = package_cli()
    if cli is None:
        return None
    try:
        r = subprocess.run([sys.executable, cli], input='{"op": "list"}', capture_output=True, text=True, timeout=20)
        out = json.loads(r.stdout or "{}")
    except (OSError, ValueError, subprocess.TimeoutExpired) as e:
        return {"error": str(e)}
    if "error" in out:
        return {"error": out["error"]}
    return [{k: s.get(k) for k in ("sessionId", "status", "pid", "cwd", "reason")} for s in out.get("sessions") or []]


def stop_daemons(done):
    cli = package_cli()
    daemons = cli_list()
    for s in daemons if isinstance(daemons, list) else []:
        if s.get("status") == "stopped":
            continue
        try:
            subprocess.run([sys.executable, cli], input=json.dumps({"op": "stop", "sessionId": s["sessionId"], "force": True}), capture_output=True, text=True, timeout=20)
            done.append("stopped daemon " + s["sessionId"])
        except (OSError, subprocess.TimeoutExpired) as e:
            done.append("could not stop daemon %s: %s" % (s["sessionId"], e))


def uninstall(done):
    config = read_json(CONFIG, {})
    settings = read_json(SETTINGS, None)
    stop_daemons(done)
    line = settings.get("statusLine") if isinstance(settings, dict) else None
    if isinstance(line, dict) and is_ours(line.get("command")):
        chain = config.get("statuslineChain")
        if chain:
            line["command"] = chain
            done.append("statusLine restored: " + chain)
        else:
            del settings["statusLine"]
            done.append("statusLine removed")
        write_json(SETTINGS, settings)
    if os.path.isdir(SHARE):
        shutil.rmtree(SHARE)
        done.append("removed " + SHARE)
    if os.path.exists(CONFIG):
        os.unlink(CONFIG)
        done.append("removed " + CONFIG)
        if not os.listdir(os.path.dirname(CONFIG)):
            os.rmdir(os.path.dirname(CONFIG))
    done.append("kept state in " + STATE)


def check():
    settings = read_json(SETTINGS, {})
    line = settings.get("statusLine") if isinstance(settings, dict) else None
    command = line.get("command") if isinstance(line, dict) else None
    config = read_json(CONFIG, None)
    claude_bin = (config or {}).get("claudeBin") if isinstance(config, dict) else None
    print(json.dumps({
        "python": sys.version.split()[0],
        "platform": sys.platform,
        "muxy": which("muxy", ".local/bin/muxy"),
        "claude": claude_bin if claude_bin and os.access(claude_bin, os.X_OK) else which("claude", ".local/bin/claude", ".claude/local/claude"),
        "claudeBin": claude_bin,
        "server": {"package": package_cli(), "note": "the app installs its package itself when it opens on this server"},
        "daemons": cli_list(),
        "statusline": {
            "state": "ours" if is_ours(command) else ("other" if command else "none"),
            "command": command,
            "installed": os.path.isfile(os.path.join(SHARE, "statusline.py")),
        },
        "config": config,
        "configPath": CONFIG,
        "stateDir": STATE,
    }, indent=2))


def main():
    ap = argparse.ArgumentParser(prog="setup.py", description="claude-chat server setup")
    ap.add_argument("--statusline", action="store_true", help="install the statusline wrapper (usage strip)")
    ap.add_argument("--open-bridge-dir", help="server dir shared with the host for open-file requests")
    ap.add_argument("--open-bridge-root", help="server path the host can map to its own folder")
    ap.add_argument("--uninstall", action="store_true", help="stop the daemons, remove the package, the statusline wrapper and the config")
    ap.add_argument("--check", action="store_true", help="print a JSON diagnosis: python, claude, package state, running daemons")
    a = ap.parse_args(sys.argv[1:])
    bridge = a.open_bridge_dir or a.open_bridge_root
    if a.check or a.uninstall:
        if a.statusline or bridge or (a.check and a.uninstall):
            fail("--check and --uninstall cannot be combined with other options")
        if a.check:
            check()
            return
        done = []
        uninstall(done)
        print("\n".join(done))
        return
    if not (a.statusline or bridge):
        fail("nothing to do (use --statusline, --open-bridge-dir/--open-bridge-root, --uninstall or --check)")
    if bool(a.open_bridge_dir) != bool(a.open_bridge_root):
        fail("--open-bridge-dir and --open-bridge-root must be given together")
    config = read_json(CONFIG, {})
    if not isinstance(config, dict):
        fail(CONFIG + " is not a JSON object")
    done = []
    if a.statusline:
        install_statusline(config, done)
    if bridge:
        d = os.path.abspath(os.path.expanduser(a.open_bridge_dir))
        root = os.path.abspath(os.path.expanduser(a.open_bridge_root))
        if not os.path.isdir(root):
            fail("open-bridge root does not exist: " + root)
        for sub in ("req", "res"):
            os.makedirs(os.path.join(d, sub), exist_ok=True)
        config["openBridge"] = {"dir": d, "root": root}
        done.append("openBridge: dir=%s root=%s" % (d, root))
    write_json(CONFIG, config)
    done.append("config " + CONFIG)
    print("\n".join(done))


try:
    main()
except OSError as e:
    fail(str(e))
